export function normalizeRobotIds(names) {
    const used = new Set();
    const out = [];
    for (const raw of names) {
        const base = raw.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
        let id = base || 'ROBOT', i = 2;
        while (used.has(id))
            id = (base || 'ROBOT') + '-' + i++;
        used.add(id);
        out.push(id);
    }
    return out;
}
